// src/App.js
import React from "react";
import { BrowserRouter as Router, Routes, Route, Link } from "react-router-dom";
import { Button, Container } from "@mui/material";
import Dashboard from "./components/Dashboard";
import Visitors from "./components/Visitors";
import AddVisitor from "./components/AddVisitor";
import NotFound from "./components/NotFound";

function App() {
  return (
    <Router>
      <Container>
        <nav>
          <Button component={Link} to="/" variant="contained" color="primary" sx={{ m: 1 }}>
            Dashboard
          </Button>
          <Button component={Link} to="/visitors" variant="contained" color="secondary" sx={{ m: 1 }}>
            Visitors
          </Button>
          <Button component={Link} to="/add-visitor" variant="contained" color="success" sx={{ m: 1 }}>
            Add Visitor
          </Button>
        </nav>

        <Routes>
          <Route path="/" element={<Dashboard />} />
          <Route path="/visitors" element={<Visitors />} />
          <Route path="/add-visitor" element={<AddVisitor />} />
          <Route path="*" element={<NotFound />} />
        </Routes>
      </Container>
    </Router>
  );
}

export default App;
